/* 資格道場 service worker — generated by src/integrations/service-worker.mjs at build time. */
const VERSION = __VERSION__;
const BASE = __BASE__;
const CORE = __CORE__;
const ASSETS = __ASSETS__;

const CORE_CACHE = `sd-core-${VERSION}`;
/** Content-hashed files never change, so one long-lived cache serves every version. */
const ASSET_CACHE = 'sd-assets';
/** Pages the learner visited, trimmed to the most recent ones. */
const RUNTIME_CACHE = 'sd-runtime';
/** Exams saved with "オフライン用に保存"; written by the page, never trimmed here. */
const SAVED_CACHE = 'sd-saved';
const RUNTIME_LIMIT = 250;
const OFFLINE_PAGE = `${BASE}offline/`;
/**
 * Servers may answer with `Vary: Origin` or `Vary: Accept-Encoding`; module scripts are requested
 * with an Origin header the precache request did not have. Our URLs fully identify the content.
 */
const MATCH = { ignoreVary: true };

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const core = await caches.open(CORE_CACHE);
      await core.addAll(CORE);
      const assets = await caches.open(ASSET_CACHE);
      const missing = [];
      for (const url of ASSETS) if (!(await assets.match(url, MATCH))) missing.push(url);
      // A failed font or chunk must not block the update; it is fetched on first use instead.
      await Promise.allSettled(missing.map((url) => assets.add(url)));
      await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys())
        if (key.startsWith('sd-core-') && key !== CORE_CACHE) await caches.delete(key);
      // Drop hashed assets that no current page references.
      const assets = await caches.open(ASSET_CACHE);
      const keep = new Set(ASSETS);
      for (const req of await assets.keys()) {
        const { pathname } = new URL(req.url);
        if (pathname.startsWith(`${BASE}_astro/`) && !keep.has(pathname)) await assets.delete(req);
      }
      await self.clients.claim();
    })(),
  );
});

async function fromCaches(request) {
  const options = { ...MATCH, ignoreSearch: true };
  return (
    (await caches.match(request, { ...options, cacheName: SAVED_CACHE })) ??
    (await caches.match(request, { ...options, cacheName: RUNTIME_CACHE })) ??
    (await caches.match(request, { ...options, cacheName: CORE_CACHE }))
  );
}

async function trim() {
  const cache = await caches.open(RUNTIME_CACHE);
  const keys = await cache.keys();
  for (const req of keys.slice(0, Math.max(0, keys.length - RUNTIME_LIMIT))) await cache.delete(req);
}

/** Pages and data: always try the network so content is fresh; fall back to what was saved. */
async function networkFirst(request, isPage) {
  try {
    const response = await fetch(request);
    if (response.ok) {
      // Clone now: the page consumes the original body as soon as it is returned.
      const forRuntime = response.clone();
      const forSaved = response.clone();
      caches.open(RUNTIME_CACHE).then((c) => c.put(request, forRuntime).then(trim));
      // Keep a saved exam current while the learner browses it online.
      caches.open(SAVED_CACHE).then(async (c) => {
        if (await c.match(request, { ...MATCH, ignoreSearch: true }))
          await c.put(new URL(request.url).pathname, forSaved);
      });
    }
    return response;
  } catch {
    const cached = await fromCaches(request);
    if (cached) return cached;
    if (isPage)
      return (await caches.match(OFFLINE_PAGE, { ...MATCH, cacheName: CORE_CACHE })) ?? Response.error();
    return Response.error();
  }
}

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request, MATCH);
  if (hit) return hit;
  const response = await fetch(request);
  if (response.ok || response.type === 'opaque') cache.put(request, response.clone());
  return response;
}

async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request, MATCH);
  const update = fetch(request)
    .then((response) => {
      if (response.ok || response.type === 'opaque') cache.put(request, response.clone());
      return response;
    })
    .catch(() => hit ?? Response.error());
  return hit ?? update;
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);

  // Web fonts (Google Fonts CSS and files).
  if (url.hostname === 'fonts.googleapis.com' || url.hostname === 'fonts.gstatic.com') {
    event.respondWith(staleWhileRevalidate(request, ASSET_CACHE));
    return;
  }
  if (url.origin !== self.location.origin || !url.pathname.startsWith(BASE)) return;
  // Downloads for 「オフライン用に保存」 go straight to the network; the page stores them itself.
  if (url.searchParams.has('sd-save')) return;
  // Search runs on Pagefind's own fragments and needs the network.
  if (url.pathname.startsWith(`${BASE}pagefind/`)) return;

  if (url.pathname.startsWith(`${BASE}_astro/`)) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }
  if (request.mode === 'navigate') {
    event.respondWith(networkFirst(request, true));
    return;
  }
  if (url.pathname.startsWith(`${BASE}data/`) || url.pathname.startsWith(`${BASE}offline/`)) {
    event.respondWith(networkFirst(request, false));
    return;
  }
  if (/\.(png|svg|ico|webmanifest)$/.test(url.pathname)) {
    event.respondWith(staleWhileRevalidate(request, CORE_CACHE));
    return;
  }
  // Anything else (e.g. prefetched pages) behaves like page data.
  event.respondWith(networkFirst(request, false));
});
